"use client";

import type { Asset, TradePrint } from "@/lib/types";
import { cn, formatClock, formatNumber } from "@/lib/utils";

/** Time & sales — simulated prints generated by the local engine. */
export function RecentTrades({ asset, trades }: { asset: Asset; trades: TradePrint[] }) {
  return (
    <div className="panel flex h-full flex-col overflow-hidden">
      <div className="panel-header">
        <span className="label-caps">Time &amp; sales</span>
        <span className="text-[9px] font-semibold uppercase tracking-wider text-slate-600">
          simulated prints
        </span>
      </div>

      <div className="grid grid-cols-4 border-b border-white/[0.06] px-3 py-1 text-[9px] font-semibold uppercase tracking-wider text-slate-500">
        <span>Time</span>
        <span className="text-right">Price</span>
        <span className="text-right">Size</span>
        <span className="text-right">Side</span>
      </div>

      <div className="flex-1 overflow-y-auto">
        {trades.length === 0 && (
          <p className="px-3 py-4 text-center text-[11px] text-slate-600">
            Waiting for the next simulated print…
          </p>
        )}
        {trades.map((t) => (
          <div
            key={t.id}
            className={cn(
              "grid grid-cols-4 px-3 py-[3px] text-[11px] odd:bg-white/[0.015]",
              t.side === "buy" ? "animate-flash-up" : "animate-flash-down",
            )}
          >
            <span className="num text-slate-500">{formatClock(t.time)}</span>
            <span
              className={cn("num text-right", t.side === "buy" ? "text-bull" : "text-bear")}
            >
              {formatNumber(t.price, t.price < 10 ? 4 : 2)}
            </span>
            <span className="num text-right text-slate-300">{formatNumber(t.size, 0)}</span>
            <span
              className={cn(
                "text-right text-[10px] font-bold uppercase",
                t.side === "buy" ? "text-bull" : "text-bear",
              )}
            >
              {t.side}
            </span>
          </div>
        ))}
      </div>

      <div className="border-t border-white/[0.06] px-3 py-2 text-[10px] text-slate-600">
        {asset.symbol} · prints are generated, not matched against an exchange.
      </div>
    </div>
  );
}
